package com.mealmate.order;import jakarta.persistence.*;import java.util.*;@Entity public class OrderModel{@Id private UUID id;private UUID customerId;private UUID restaurantId;@Enumerated(EnumType.STRING)private OrderStatus status;private boolean failPayment;private boolean failDeliveryAssignment;@Column(unique=true)private String idempotencyKey;protected OrderModel(){}OrderModel(UUID c,UUID r,boolean p,boolean d,String k){id=UUID.randomUUID();customerId=c;restaurantId=r;failPayment=p;failDeliveryAssignment=d;idempotencyKey=k;status=OrderStatus.PENDING;}public UUID getId(){return id;}public OrderStatus getStatus(){return status;}public void setStatus(OrderStatus s){status=s;}public boolean isFailPayment(){return failPayment;}public boolean isFailDeliveryAssignment(){return failDeliveryAssignment;}}
